import { useRef } from 'react';

import { cloneDeep } from 'lodash';

import backgroundApiProxy from '@onekeyhq/kit/src/background/instance/backgroundApiProxy';
import { ContextJotaiActionsBase } from '@onekeyhq/kit/src/states/jotai/utils/ContextJotaiActionsBase';
import {
  EAppEventBusNames,
  appEventBus,
} from '@onekeyhq/shared/src/eventBus/appEventBus';
import { memoFn } from '@onekeyhq/shared/src/utils/cacheUtils';
import { getMarketWatchlistKey } from '@onekeyhq/shared/src/utils/marketWatchlistIdentity';
import sortUtils from '@onekeyhq/shared/src/utils/sortUtils';
import {
  equalTokenNoCaseSensitive,
  normalizeTokenContractAddress,
} from '@onekeyhq/shared/src/utils/tokenUtils';
import type { IMarketWatchListItemV2 } from '@onekeyhq/shared/types/market';
import type {
  IMarketPerpsInfo,
  IMarketTokenDetail,
  IMarketTokenDetailPreview,
  IMarketTokenDetailResponse,
  IMarketTokenDetailWebsocket,
} from '@onekeyhq/shared/types/marketV2';
import { ERookieTaskType } from '@onekeyhq/shared/types/rookieGuide';

import {
  contextAtomMethod,
  isNativeAtom,
  marketWatchListV2Atom,
  marketWatchListV2RefreshRequestIdAtom,
  networkIdAtom,
  perpsInfoAtom,
  showWatchlistOnlyAtom,
  tokenAddressAtom,
  tokenDetailAtom,
  tokenDetailLoadingAtom,
  tokenDetailPreviewAtom,
  tokenDetailRequestIdAtom,
  tokenDetailSwrScopeAtom,
  tokenDetailWebsocketAtom,
} from './atoms';
import { marketTokenDetailSnapshotCache } from './marketSnapshotCaches';

export const homeResettingFlags: Record<string, number> = {};

const uniqByFn = getMarketWatchlistKey;

let watchQueue: Promise<unknown> = Promise.resolve();
const watchOps = new Map<string, [boolean, Promise<unknown>]>();

function runOp<T>(keys: string[], add: boolean, mutation: () => Promise<T>) {
  const op = watchQueue
    .then(mutation, mutation)
    .finally(() => keys.forEach((key) => watchOps.delete(key)));
  keys.forEach((key) => watchOps.set(key, [add, op]));
  watchQueue = op.catch(() => undefined);
  return op;
}

async function waitOp(key: string, add: boolean) {
  const op = watchOps.get(key)!;
  await (op[0] === add ? op[1] : op[1].catch(() => undefined));
  return op[0] === add;
}

const CHART_PRICE_FRESHNESS_MS = 10_000;

function isSameMarketTokenDetail({
  tokenDetail,
  tokenAddress,
  networkId,
}: {
  tokenDetail?: IMarketTokenDetail;
  tokenAddress: string;
  networkId: string;
}) {
  if (!tokenDetail) {
    return false;
  }

  return equalTokenNoCaseSensitive({
    token1: {
      networkId,
      contractAddress: tokenAddress,
    },
    token2: {
      networkId: tokenDetail.networkId || '',
      contractAddress: tokenDetail.address || '',
    },
  });
}

class ContextJotaiActionsMarketV2 extends ContextJotaiActionsBase {
  // Token Detail Actions
  setTokenDetail = contextAtomMethod(
    (_, set, payload: IMarketTokenDetail | undefined) => {
      set(tokenDetailAtom(), payload);
    },
  );

  setTokenDetailLoading = contextAtomMethod((get, set, payload: boolean) => {
    if (!payload) {
      set(tokenDetailRequestIdAtom(), get(tokenDetailRequestIdAtom()) + 1);
    }
    set(tokenDetailLoadingAtom(), payload);
  });

  setTokenDetailPreview = contextAtomMethod(
    (_, set, payload: IMarketTokenDetailPreview | undefined) => {
      set(tokenDetailPreviewAtom(), payload);
      if (!payload) {
        return;
      }
      set(tokenAddressAtom(), payload.address);
      set(networkIdAtom(), payload.networkId);
      set(isNativeAtom(), Boolean(payload.isNative));
    },
  );

  prepareTokenDetailPreview = contextAtomMethod(
    (
      get,
      set,
      payload: IMarketTokenDetailPreview | undefined,
      retainedTarget?: {
        tokenAddress: string;
        networkId: string;
        isNative: boolean;
      },
    ) => {
      const detail = get(tokenDetailAtom());
      const preview = get(tokenDetailPreviewAtom());
      // Retained routes may reconnect their effects without changing identity.
      // Read the shared store now: another route may have owned it while hidden.
      if (
        retainedTarget &&
        get(tokenAddressAtom()) === retainedTarget.tokenAddress &&
        get(networkIdAtom()) === retainedTarget.networkId &&
        get(isNativeAtom()) === Boolean(retainedTarget.isNative) &&
        (!detail ||
          isSameMarketTokenDetail({
            tokenDetail: detail,
            ...retainedTarget,
          })) &&
        (!preview ||
          (preview.address === retainedTarget.tokenAddress &&
            preview.networkId === retainedTarget.networkId))
      ) {
        return;
      }
      set(tokenDetailRequestIdAtom(), get(tokenDetailRequestIdAtom()) + 1);
      set(tokenDetailAtom(), undefined);
      set(tokenDetailPreviewAtom(), payload);
      set(tokenDetailLoadingAtom(), false);
      set(tokenDetailWebsocketAtom(), undefined);
      set(perpsInfoAtom(), undefined);
      set(
        tokenAddressAtom(),
        retainedTarget?.tokenAddress ?? payload?.address ?? '',
      );
      set(
        networkIdAtom(),
        retainedTarget?.networkId ?? payload?.networkId ?? '',
      );
      set(
        isNativeAtom(),
        Boolean(retainedTarget?.isNative ?? payload?.isNative),
      );
    },
  );

  clearTokenDetailPreview = contextAtomMethod((_, set) => {
    set(tokenDetailPreviewAtom(), undefined);
  });

  setTokenAddress = contextAtomMethod((_, set, payload: string) => {
    set(tokenAddressAtom(), payload);
  });

  setNetworkId = contextAtomMethod((_, set, payload: string) => {
    set(networkIdAtom(), payload);
  });

  setIsNative = contextAtomMethod((_, set, payload: boolean) => {
    set(isNativeAtom(), payload);
  });

  setTokenDetailWebsocket = contextAtomMethod(
    (_, set, payload: IMarketTokenDetailWebsocket | undefined) => {
      set(tokenDetailWebsocketAtom(), payload);
    },
  );

  setPerpsInfo = contextAtomMethod(
    (_, set, payload: IMarketPerpsInfo | undefined) => {
      set(perpsInfoAtom(), payload);
    },
  );

  clearTokenDetail = contextAtomMethod((get, set) => {
    set(tokenDetailRequestIdAtom(), get(tokenDetailRequestIdAtom()) + 1);
    set(tokenDetailAtom(), undefined);
    set(tokenDetailPreviewAtom(), undefined);
    set(tokenDetailLoadingAtom(), false);
    set(tokenAddressAtom(), '');
    set(networkIdAtom(), '');
    set(isNativeAtom(), false);
    set(tokenDetailWebsocketAtom(), undefined);
    set(perpsInfoAtom(), undefined);
  });

  prepareStockTokenDetail = contextAtomMethod(
    (
      get,
      set,
      target: { tokenAddress: string; networkId: string; isNative?: boolean },
    ) => {
      // A stock route can be entered before its token variant is resolved.
      // Clear the previous identity so it cannot be rendered for the new stock.
      if (!target.networkId || (!target.tokenAddress && !target.isNative)) {
        set(tokenDetailRequestIdAtom(), get(tokenDetailRequestIdAtom()) + 1);
        set(tokenDetailAtom(), undefined);
        set(tokenDetailPreviewAtom(), undefined);
        set(tokenDetailLoadingAtom(), false);
        set(tokenAddressAtom(), '');
        set(networkIdAtom(), '');
        set(isNativeAtom(), false);
        set(tokenDetailWebsocketAtom(), undefined);
        set(perpsInfoAtom(), undefined);
        return;
      }

      // Re-entering the same stock variant must preserve loaded data and any
      // in-flight request. Clearing here would leave the existing request key
      // unchanged, so useAutoRefreshTokenDetail would not start it again.
      if (
        get(isNativeAtom()) === Boolean(target.isNative) &&
        equalTokenNoCaseSensitive({
          token1: {
            networkId: get(networkIdAtom()),
            contractAddress: get(tokenAddressAtom()),
          },
          token2: {
            networkId: target.networkId,
            contractAddress: target.tokenAddress,
          },
        })
      ) {
        return;
      }

      set(tokenDetailRequestIdAtom(), get(tokenDetailRequestIdAtom()) + 1);
      set(tokenDetailAtom(), undefined);
      set(tokenDetailPreviewAtom(), undefined);
      set(tokenDetailLoadingAtom(), false);
      set(tokenAddressAtom(), target.tokenAddress);
      set(networkIdAtom(), target.networkId);
      set(isNativeAtom(), Boolean(target.isNative));
      set(tokenDetailWebsocketAtom(), undefined);
      set(perpsInfoAtom(), undefined);
    },
  );

  // Fill an empty detail from the last response for this token so a revisit
  // renders real values on its first frame; the running poll replaces it.
  seedTokenDetailFromCache = contextAtomMethod(
    (
      get,
      set,
      payload: { tokenAddress: string; networkId: string; swrKey: string },
    ) => {
      const { tokenAddress, networkId, swrKey } = payload;
      // Same token in the same scope: what is on screen already came from this
      // key. A scope change (currency, locale) keeps the token identity but
      // makes the displayed fields stale, so it must fall through and seed.
      if (
        get(tokenDetailSwrScopeAtom()) === swrKey &&
        isSameMarketTokenDetail({
          tokenDetail: get(tokenDetailAtom()),
          tokenAddress,
          networkId,
        })
      ) {
        return;
      }
      // Only seed the identity the atoms currently point at.
      if (
        !equalTokenNoCaseSensitive({
          token1: {
            networkId: get(networkIdAtom()),
            contractAddress: get(tokenAddressAtom()),
          },
          token2: { networkId, contractAddress: tokenAddress },
        })
      ) {
        return;
      }
      // The cache applies its own max age, so a stale record reads as a miss.
      const cached = marketTokenDetailSnapshotCache.get(swrKey);
      if (
        !cached?.data?.token ||
        !isSameMarketTokenDetail({
          tokenDetail: cached.data.token,
          tokenAddress,
          networkId,
        })
      ) {
        return;
      }
      set(tokenDetailAtom(), cached.data.token);
      set(tokenDetailWebsocketAtom(), cached.data.websocket);
      set(perpsInfoAtom(), cached.data.perpsInfo);
      set(tokenDetailSwrScopeAtom(), swrKey);
    },
  );

  applyChartPriceUpdate = contextAtomMethod(
    (
      get,
      set,
      payload: {
        tokenAddress?: string;
        networkId?: string;
        price: string;
        lastUpdated?: number;
      },
    ) => {
      const tokenDetail = get(tokenDetailAtom());
      if (!tokenDetail) {
        return;
      }

      const numericPrice = Number(payload.price);
      if (!Number.isFinite(numericPrice) || numericPrice <= 0) {
        return;
      }

      if (
        payload.networkId &&
        tokenDetail.networkId &&
        tokenDetail.networkId !== payload.networkId
      ) {
        return;
      }

      const isNative = get(isNativeAtom()) || tokenDetail.isNative;
      if (!payload.tokenAddress && !isNative) {
        return;
      }

      if (
        payload.tokenAddress &&
        !equalTokenNoCaseSensitive({
          token1: {
            networkId: payload.networkId || tokenDetail.networkId || '',
            contractAddress: payload.tokenAddress,
          },
          token2: {
            networkId: tokenDetail.networkId || payload.networkId || '',
            contractAddress: tokenDetail.address || '',
          },
        })
      ) {
        return;
      }

      const chartPriceUpdatedAt = Date.now();
      const lastUpdated =
        payload.lastUpdated ?? tokenDetail.lastUpdated ?? chartPriceUpdatedAt;

      if (tokenDetail.price === payload.price) {
        set(tokenDetailAtom(), {
          ...tokenDetail,
          lastUpdated,
          chartPriceUpdatedAt,
        });
        return;
      }

      set(tokenDetailAtom(), {
        ...tokenDetail,
        price: payload.price,
        lastUpdated,
        chartPriceUpdatedAt,
      });
    },
  );

  changeActiveToken = contextAtomMethod(
    async (
      get,
      set,
      payload: {
        tokenAddress: string;
        networkId: string;
        isNative: boolean;
        tokenDetailPreview?: IMarketTokenDetailPreview;
      },
    ) => {
      const { tokenAddress, networkId, isNative, tokenDetailPreview } = payload;
      const nextPreview =
        tokenDetailPreview?.address === tokenAddress &&
        tokenDetailPreview.networkId === networkId
          ? tokenDetailPreview
          : undefined;
      // Set atom values directly — `this.xxx.call(set)` doesn't work
      // because `this` is not the class instance inside contextAtomMethod.
      const requestId = get(tokenDetailRequestIdAtom()) + 1;
      set(tokenDetailRequestIdAtom(), requestId);
      set(tokenDetailAtom(), undefined);
      set(tokenDetailPreviewAtom(), nextPreview);
      set(tokenDetailWebsocketAtom(), undefined);
      set(perpsInfoAtom(), undefined);
      set(tokenAddressAtom(), tokenAddress);
      set(networkIdAtom(), networkId);
      set(isNativeAtom(), isNative);

      let isStale = false;
      const isCurrentRequest = () =>
        get(tokenDetailRequestIdAtom()) === requestId;
      try {
        set(tokenDetailLoadingAtom(), true);
        const response =
          await backgroundApiProxy.serviceMarketV2.fetchMarketTokenDetailByTokenAddress(
            tokenAddress,
            networkId,
          );

        // Stale check: discard if user already switched to a different token
        const currentAddress = get(tokenAddressAtom());
        const currentNetworkId = get(networkIdAtom());
        if (
          !isCurrentRequest() ||
          currentAddress !== tokenAddress ||
          currentNetworkId !== networkId
        ) {
          isStale = true;
          return;
        }

        const responseData = response as unknown as IMarketTokenDetailResponse;
        if (
          typeof responseData?.data?.token?.name === 'undefined' ||
          responseData.data.token.name === ''
        ) {
          set(tokenDetailAtom(), undefined);
          set(tokenDetailPreviewAtom(), undefined);
          set(tokenDetailWebsocketAtom(), undefined);
          set(perpsInfoAtom(), undefined);
          return;
        }
        set(tokenDetailAtom(), {
          ...responseData.data.token,
          networkId,
        });
        set(tokenDetailPreviewAtom(), undefined);
        set(tokenDetailWebsocketAtom(), responseData.data.websocket);
        set(perpsInfoAtom(), responseData.data.perpsInfo);
      } catch (error) {
        console.error('Failed to fetch token detail:', error);
        const currentAddress = get(tokenAddressAtom());
        const currentNetworkId = get(networkIdAtom());
        if (
          !isCurrentRequest() ||
          currentAddress !== tokenAddress ||
          currentNetworkId !== networkId
        ) {
          isStale = true;
        } else {
          set(tokenDetailAtom(), undefined);
          set(tokenDetailPreviewAtom(), undefined);
          set(tokenDetailWebsocketAtom(), undefined);
          set(perpsInfoAtom(), undefined);
        }
      } finally {
        // Skip loading reset when stale — another caller (fetchTokenDetail
        // from useAutoRefreshTokenDetail) may already be in-flight with
        // loading=true for the new token.
        if (!isStale) {
          set(tokenDetailLoadingAtom(), false);
        }
      }
    },
  );

  // ShowWatchlistOnly Actions
  setShowWatchlistOnly = contextAtomMethod((_, set, payload: boolean) => {
    set(showWatchlistOnlyAtom(), payload);
    // Emit app event when showWatchlistOnly changes
    appEventBus.emit(EAppEventBusNames.MarketWatchlistOnlyChanged, {
      showWatchlistOnly: payload,
    });
  });

  toggleShowWatchlistOnly = contextAtomMethod((get, set) => {
    const current = get(showWatchlistOnlyAtom());
    const newValue = !current;
    set(showWatchlistOnlyAtom(), newValue);
    // Emit app event when showWatchlistOnly changes
    appEventBus.emit(EAppEventBusNames.MarketWatchlistOnlyChanged, {
      showWatchlistOnly: newValue,
    });
  });

  fetchTokenDetail = contextAtomMethod(
    async (
      get,
      set,
      tokenAddress: string,
      networkId: string,
      options?: { swrKey?: string },
    ) => {
      const requestId = get(tokenDetailRequestIdAtom()) + 1;
      set(tokenDetailRequestIdAtom(), requestId);
      let isStale = false;
      const isCurrentRequest = () =>
        get(tokenDetailRequestIdAtom()) === requestId;
      try {
        set(tokenDetailLoadingAtom(), true);

        const response =
          await backgroundApiProxy.serviceMarketV2.fetchMarketTokenDetailByTokenAddress(
            tokenAddress,
            networkId,
          );

        // Stale check first: discard if user already switched to a different
        // token via changeActiveToken during this async fetch. Must run before
        // the data validity check so that early returns don't clobber loading.
        const currentAddress = get(tokenAddressAtom());
        const currentNetworkId = get(networkIdAtom());
        if (!isCurrentRequest()) {
          isStale = true;
          return;
        }
        if (currentAddress !== tokenAddress && currentAddress !== '') {
          isStale = true;
          return;
        }
        if (currentNetworkId !== networkId && currentNetworkId !== '') {
          isStale = true;
          return;
        }

        // Assume new format with data.token and data.websocket
        const responseData = response as unknown as IMarketTokenDetailResponse;

        const currentTokenDetail = get(tokenDetailAtom());

        if (
          typeof responseData?.data?.token?.name === 'undefined' ||
          responseData.data.token.name === ''
        ) {
          if (
            isSameMarketTokenDetail({
              tokenDetail: currentTokenDetail,
              tokenAddress,
              networkId,
            })
          ) {
            console.warn(
              'Token detail is not available, keep current token detail',
            );
            return currentTokenDetail;
          }

          console.warn('Token detail is not available');
          set(tokenDetailAtom(), undefined);
          set(tokenDetailPreviewAtom(), undefined);
          set(tokenDetailWebsocketAtom(), undefined);
          set(perpsInfoAtom(), undefined);
          if (options?.swrKey) {
            marketTokenDetailSnapshotCache.remove(options.swrKey);
          }
          return;
        }

        // Extract token, websocket and perpsInfo from response format
        const tokenData = {
          ...responseData.data.token,
          networkId,
        };
        const websocketConfig = responseData.data.websocket;
        const perpsInfo = responseData.data.perpsInfo;

        // Preserve chart-updated price only while it is fresh.
        const isSameToken =
          currentTokenDetail &&
          isSameMarketTokenDetail({
            tokenDetail: currentTokenDetail,
            tokenAddress,
            networkId,
          });
        const chartPriceUpdatedAt = currentTokenDetail?.chartPriceUpdatedAt;
        const hasFreshKLinePrice =
          isSameToken &&
          typeof chartPriceUpdatedAt === 'number' &&
          Number.isFinite(chartPriceUpdatedAt) &&
          Date.now() - chartPriceUpdatedAt < CHART_PRICE_FRESHNESS_MS;

        const finalTokenData = hasFreshKLinePrice
          ? {
              ...tokenData,
              price: currentTokenDetail.price,
              lastUpdated: currentTokenDetail.lastUpdated,
              chartPriceUpdatedAt,
            }
          : tokenData;

        set(tokenDetailAtom(), finalTokenData);
        set(tokenDetailPreviewAtom(), undefined);
        set(tokenDetailWebsocketAtom(), websocketConfig);
        set(perpsInfoAtom(), perpsInfo);
        if (options?.swrKey) {
          marketTokenDetailSnapshotCache.set(options.swrKey, {
            token: tokenData,
            websocket: websocketConfig,
            perpsInfo,
          });
          // This response is the scope now, so a seed for the same key cannot
          // put an older cached copy back over it.
          set(tokenDetailSwrScopeAtom(), options.swrKey);
        }

        return finalTokenData;
      } catch (error) {
        console.error('Failed to fetch token detail:', error);
        // Only clear atoms if we're still on the same token
        const currentAddress = get(tokenAddressAtom());
        const currentNetworkId = get(networkIdAtom());
        if (!isCurrentRequest()) {
          isStale = true;
        } else if (
          (currentAddress === tokenAddress || currentAddress === '') &&
          (currentNetworkId === networkId || currentNetworkId === '')
        ) {
          // A failed refresh must not unmount the current quotes and chart.
          // Never retain details belonging to a different token or network.
          if (
            !isSameMarketTokenDetail({
              tokenDetail: get(tokenDetailAtom()),
              tokenAddress,
              networkId,
            })
          ) {
            set(tokenDetailAtom(), undefined);
            set(tokenDetailPreviewAtom(), undefined);
            set(tokenDetailWebsocketAtom(), undefined);
            set(perpsInfoAtom(), undefined);
          }
        } else {
          isStale = true;
        }
        throw error;
      } finally {
        if (!isStale) {
          set(tokenDetailLoadingAtom(), false);
        }
      }
    },
  );

  // Existing WatchList Actions
  flushWatchListV2Atom = contextAtomMethod(
    (_, set, payload: IMarketWatchListItemV2[]) => {
      const result = { data: payload };
      set(marketWatchListV2Atom(), result);
    },
  );

  invalidateWatchListV2Refresh = contextAtomMethod((get, set) => {
    set(
      marketWatchListV2RefreshRequestIdAtom(),
      get(marketWatchListV2RefreshRequestIdAtom()) + 1,
    );
  });

  // ------------------------------------------------------------
  refreshWatchListV2 = contextAtomMethod(async (get, set) => {
    if (watchOps.size) {
      return;
    }
    const requestId = get(marketWatchListV2RefreshRequestIdAtom()) + 1;
    set(marketWatchListV2RefreshRequestIdAtom(), requestId);
    const data =
      await backgroundApiProxy.serviceMarketV2.getMarketWatchListV2();
    if (
      watchOps.size ||
      get(marketWatchListV2RefreshRequestIdAtom()) !== requestId
    ) {
      return;
    }
    return this.flushWatchListV2Atom.call(set, data.data);
  });

  isInWatchListV2 = contextAtomMethod(
    (get, _set, chainId: string, contractAddress: string) => {
      const prev = get(marketWatchListV2Atom());
      return !!prev.data?.find((i) =>
        equalTokenNoCaseSensitive({
          token1: { networkId: chainId, contractAddress },
          token2: { networkId: i.chainId, contractAddress: i.contractAddress },
        }),
      );
    },
  );

  addIntoWatchListV2 = contextAtomMethod(
    async (
      get,
      set,
      payload: IMarketWatchListItemV2 | IMarketWatchListItemV2[],
    ) => {
      let params: IMarketWatchListItemV2[] = !Array.isArray(payload)
        ? [payload]
        : payload;
      params = params.map((item) => ({
        ...item,
        contractAddress:
          normalizeTokenContractAddress({
            networkId: item.chainId,
            contractAddress: item.contractAddress,
          }) || '',
      }));
      for (const item of params) {
        const key = uniqByFn(item);
        while (watchOps.has(key)) {
          if (await waitOp(key, true)) {
            params = params.filter((i) => uniqByFn(i) !== key);
            break;
          }
        }
      }
      if (!params.length) {
        return;
      }

      const prev = get(marketWatchListV2Atom());
      if (!prev.isMounted) {
        return;
      }
      this.invalidateWatchListV2Refresh.call(set);
      const prevKeys = new Set(prev.data.map(uniqByFn));
      const newKeys = new Set(
        params.filter((item) => !prevKeys.has(uniqByFn(item))).map(uniqByFn),
      );
      const keys = params.map(uniqByFn);
      const data = sortUtils.buildSortedList({
        oldList: prev.data,
        saveItems: params,
        uniqByFn,
      });
      set(marketWatchListV2Atom(), { ...prev, data });

      await runOp(keys, true, async () => {
        try {
          await backgroundApiProxy.serviceMarketV2.addMarketWatchListV2({
            watchList: params,
            callerName: 'jotaiContextActions_addIntoWatchListV2',
          });
        } catch (error) {
          const current = get(marketWatchListV2Atom());
          set(marketWatchListV2Atom(), {
            ...current,
            data: current.data.filter((item) => !newKeys.has(uniqByFn(item))),
          });
          throw error;
        }
      });
      if (!watchOps.size) {
        await this.refreshWatchListV2.call(set).catch(() => undefined);
      }
      void backgroundApiProxy.serviceRookieGuide.recordTaskCompleted(
        ERookieTaskType.MARKET,
      );
    },
  );

  removeFromWatchListV2 = contextAtomMethod(
    async (
      get,
      set,
      chainId: string,
      contractAddress: string,
      listing?: Pick<IMarketWatchListItemV2, 'assetId' | 'stockId'>,
    ) => {
      // eslint-disable-next-line no-param-reassign
      contractAddress =
        normalizeTokenContractAddress({
          networkId: chainId,
          contractAddress,
        }) || '';
      const identity = { chainId, contractAddress, ...listing };
      const key = uniqByFn(identity);
      while (watchOps.has(key)) {
        if (await waitOp(key, false)) {
          return;
        }
      }

      const prev = get(marketWatchListV2Atom());
      if (!prev.isMounted) {
        return;
      }

      this.invalidateWatchListV2Refresh.call(set);
      // Immediately update local state using proper token matching
      const newData = prev.data.filter(
        (item) =>
          getMarketWatchlistKey(item) !== getMarketWatchlistKey(identity),
      );

      set(marketWatchListV2Atom(), { ...prev, data: newData });

      await runOp([key], false, async () => {
        try {
          await backgroundApiProxy.serviceMarketV2.removeMarketWatchListV2({
            items: [identity],
            callerName: 'jotaiContextActions_removeFromWatchListV2',
          });
        } catch (error) {
          const current = get(marketWatchListV2Atom());
          const data = sortUtils.buildSortedList({
            oldList: current.data,
            saveItems: prev.data.filter((item) => !newData.includes(item)),
            uniqByFn,
          });
          set(marketWatchListV2Atom(), { ...current, data });
          throw error;
        }
      });
      if (!watchOps.size) {
        await this.refreshWatchListV2.call(set).catch(() => undefined);
      }
    },
  );

  isPerpsInWatchListV2 = contextAtomMethod((get, _set, perpsCoin: string) => {
    const prev = get(marketWatchListV2Atom());
    return !!prev.data?.find((i) => i.perpsCoin === perpsCoin);
  });

  // Perps watchlist: add a perps coin to the watchlist
  addPerpsIntoWatchListV2 = contextAtomMethod(
    async (get, set, perpsCoin: string) => {
      const prev = get(marketWatchListV2Atom());
      if (!prev.isMounted) {
        return;
      }

      const [sortIndex] = sortUtils.buildTopSortIndexes({
        oldList: prev.data,
        count: 1,
      });
      const item: IMarketWatchListItemV2 = {
        chainId: '',
        contractAddress: '',
        perpsCoin,
        // Without an index the save fills in "after the last item", which
        // sank every perps favorite below the spot ones.
        sortIndex,
      };

      this.invalidateWatchListV2Refresh.call(set);
      const sortedNewData = sortUtils.buildSortedList({
        oldList: prev.data,
        saveItems: [item],
        uniqByFn,
      });
      set(marketWatchListV2Atom(), { ...prev, data: sortedNewData });

      try {
        await backgroundApiProxy.serviceMarketV2.addMarketWatchListV2({
          watchList: [item],
          callerName: 'jotaiContextActions_addPerpsIntoWatchListV2',
        });
      } catch (error) {
        await this.refreshWatchListV2.call(set);
        throw error;
      }
      await this.refreshWatchListV2.call(set);

      // Sync to Perps TokenSelector favorites
      void backgroundApiProxy.serviceMarketV2.syncToPerpsAtom({
        coin: perpsCoin,
        action: 'add',
      });
    },
  );

  // Perps watchlist: remove a perps coin from the watchlist
  removePerpsFromWatchListV2 = contextAtomMethod(
    async (get, set, perpsCoin: string) => {
      const prev = get(marketWatchListV2Atom());
      if (!prev.isMounted) {
        return;
      }

      this.invalidateWatchListV2Refresh.call(set);
      const newData = prev.data.filter((item) => item.perpsCoin !== perpsCoin);
      set(marketWatchListV2Atom(), { ...prev, data: newData });

      try {
        await backgroundApiProxy.serviceMarketV2.removeMarketWatchListV2({
          items: [{ chainId: '', contractAddress: '', perpsCoin }],
          callerName: 'jotaiContextActions_removePerpsFromWatchListV2',
        });
      } catch (error) {
        await this.refreshWatchListV2.call(set);
        throw error;
      }
      await this.refreshWatchListV2.call(set);

      // Sync to Perps TokenSelector favorites
      void backgroundApiProxy.serviceMarketV2.syncToPerpsAtom({
        coin: perpsCoin,
        action: 'remove',
      });
    },
  );

  moveToTopV2 = contextAtomMethod(
    async (get, set, payload: IMarketWatchListItemV2) => {
      const prev = get(marketWatchListV2Atom());
      if (!prev.isMounted) {
        return;
      }
      const firstItem = prev?.data?.[0];
      if (
        firstItem &&
        getMarketWatchlistKey(firstItem) === getMarketWatchlistKey(payload)
      )
        return;
      await this.sortWatchListV2Items.call(set, {
        target: payload,
        prev: undefined,
        next: firstItem,
      });
    },
  );

  sortWatchListV2Items = contextAtomMethod(
    async (
      get,
      set,
      payload: {
        target: IMarketWatchListItemV2;
        prev: IMarketWatchListItemV2 | undefined;
        next: IMarketWatchListItemV2 | undefined;
      },
    ) => {
      const { target, prev, next } = payload;
      const oldItemsResult = get(marketWatchListV2Atom());
      if (!oldItemsResult.isMounted) {
        return;
      }

      // Resolve current sortIndex from atom state to avoid stale values
      // from callers (e.g. edit dialog local state).
      const resolveFromAtom = (
        item: IMarketWatchListItemV2 | undefined,
      ): IMarketWatchListItemV2 | undefined => {
        if (!item) return undefined;
        const key = uniqByFn(item);
        const found = oldItemsResult.data.find((i) => uniqByFn(i) === key);
        return found ?? item;
      };

      const resolvedTarget = resolveFromAtom(target)!;
      const resolvedPrev = resolveFromAtom(prev);
      const resolvedNext = resolveFromAtom(next);

      const newSortIndex = sortUtils.buildNewSortIndex({
        target: resolvedTarget,
        prev: resolvedPrev,
        next: resolvedNext,
      });

      const watchList = [
        cloneDeep({
          ...resolvedTarget,
          sortIndex: newSortIndex,
        }),
      ];

      this.invalidateWatchListV2Refresh.call(set);
      const newList = sortUtils.buildSortedList({
        oldList: oldItemsResult.data,
        saveItems: watchList,
        uniqByFn,
      });
      this.flushWatchListV2Atom.call(set, newList);

      await backgroundApiProxy.serviceMarketV2.addMarketWatchListV2({
        watchList,
        callerName: 'jotaiContextActions_sortWatchListV2Items',
      });
      await this.refreshWatchListV2.call(set);
    },
  );

  saveWatchListV2 = contextAtomMethod(
    async (_get, set, payload: IMarketWatchListItemV2[]) => {
      await this.addIntoWatchListV2.call(set, payload);
    },
  );

  clearAllWatchListV2 = contextAtomMethod(async (get, set) => {
    const prev = get(marketWatchListV2Atom());
    if (!prev.isMounted) {
      return;
    }

    this.invalidateWatchListV2Refresh.call(set);
    // Immediately update local state
    set(marketWatchListV2Atom(), { ...prev, data: [] });

    // Asynchronously call API without waiting for result
    await backgroundApiProxy.serviceMarketV2.clearAllMarketWatchListV2();
  });
}

const createActions = memoFn(() => new ContextJotaiActionsMarketV2());

export function useWatchListV2Actions() {
  const actions = createActions();
  const addIntoWatchListV2 = actions.addIntoWatchListV2.use();
  const removeFromWatchListV2 = actions.removeFromWatchListV2.use();
  const isInWatchListV2 = actions.isInWatchListV2.use();
  const saveWatchListV2 = actions.saveWatchListV2.use();
  const refreshWatchListV2 = actions.refreshWatchListV2.use();
  const sortWatchListV2Items = actions.sortWatchListV2Items.use();
  const moveToTopV2 = actions.moveToTopV2.use();
  const clearAllWatchListV2 = actions.clearAllWatchListV2.use();
  const isPerpsInWatchListV2 = actions.isPerpsInWatchListV2.use();
  const addPerpsIntoWatchListV2 = actions.addPerpsIntoWatchListV2.use();
  const removePerpsFromWatchListV2 = actions.removePerpsFromWatchListV2.use();
  return useRef({
    isInWatchListV2,
    addIntoWatchListV2,
    removeFromWatchListV2,
    saveWatchListV2,
    refreshWatchListV2,
    sortWatchListV2Items,
    moveToTopV2,
    clearAllWatchListV2,
    isPerpsInWatchListV2,
    addPerpsIntoWatchListV2,
    removePerpsFromWatchListV2,
  });
}

